package main

import (
	"bufio"
	"encoding/json"
	"flag"
	"fmt"
	"os"
)

// locribRecord is the exact output shape. Field order is fixed so the emitted
// JSON is byte-stable across runs.
type locribRecord struct {
	Prefix        string   `json:"prefix"`
	NextHop       string   `json:"next_hop"`
	ASPath        []uint32 `json:"as_path"`
	DecisiveStage string   `json:"decisive_stage"`
	MultipathSet  []string `json:"multipath_set"`
}

func main() {
	in := flag.String("in", "rib.jsonl", "input RIB-in JSONL file")
	out := flag.String("out", "locrib.jsonl", "output Loc-RIB JSONL file")
	localAS := flag.Uint("local-as", 0, "override local ASN for AS_PATH loop rejection")
	clusterID := flag.String("cluster-id", "", "override local cluster ID for CLUSTER_LIST loop rejection")
	routerID := flag.String("router-id", "", "override local router ID for ORIGINATOR_ID checks")
	rejectOrig := flag.Bool("reject-originator-id", false, "also reject paths whose ORIGINATOR_ID equals the local router ID (RFC 4456)")
	flag.Parse()

	routes, cfg, err := readRIB(*in)
	if err != nil {
		fmt.Fprintln(os.Stderr, "bgpselect:", err)
		os.Exit(1)
	}
	if *localAS != 0 {
		cfg.LocalAS = uint32(*localAS)
	}
	if *clusterID != "" {
		cfg.ClusterID = *clusterID
	}
	if *routerID != "" {
		cfg.RouterID = *routerID
	}

	decisions := ProcessPrefix(routes, cfg, *rejectOrig)

	f, err := os.Create(*out)
	if err != nil {
		fmt.Fprintln(os.Stderr, "bgpselect:", err)
		os.Exit(1)
	}
	defer f.Close()
	w := bufio.NewWriter(f)
	enc := json.NewEncoder(w)
	enc.SetEscapeHTML(false)
	for _, d := range decisions {
		rec := locribRecord{
			Prefix:        d.Prefix,
			NextHop:       d.NextHop,
			ASPath:        d.ASPath,
			DecisiveStage: d.DecisiveStage,
			MultipathSet:  d.Multipath,
		}
		if err := enc.Encode(rec); err != nil {
			fmt.Fprintln(os.Stderr, "bgpselect:", err)
			os.Exit(1)
		}
	}
	if err := w.Flush(); err != nil {
		fmt.Fprintln(os.Stderr, "bgpselect:", err)
		os.Exit(1)
	}
}

// readRIB parses the JSONL dump. Both a leading config line and per-line
// config fields are accepted. Any line that carries a prefix is a route.
func readRIB(path string) ([]Route, Config, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, Config{}, err
	}
	defer f.Close()

	var routes []Route
	var cfg Config
	mrt := newMRTState()
	sc := bufio.NewScanner(f)
	sc.Buffer(make([]byte, 1024*1024), 16*1024*1024)
	line := 0
	for sc.Scan() {
		line++
		raw := sc.Bytes()
		trimmed := bytesTrimSpace(raw)
		if len(trimmed) == 0 {
			continue
		}
		// A bare hex string is an MRT record.
		if trimmed[0] != '{' {
			if rs, err := mrt.feed(string(trimmed), cfg); err == nil {
				routes = append(routes, rs...)
				continue
			}
		}
		var m map[string]json.RawMessage
		if err := json.Unmarshal(raw, &m); err != nil {
			return nil, cfg, fmt.Errorf("line %d: %w", line, err)
		}
		if _, isRoute := rawLookup(m, "prefix", "nlri", "network"); isRoute {
			routes = append(routes, ParseRoute(m))
			continue
		}
		// An embedded hex MRT record.
		if rawHex, ok := rawLookup(m, "mrt", "mrt_hex", "record", "hex", "raw", "data"); ok {
			if hs, err := decodeString(rawHex); err == nil {
				if rs, err := mrt.feed(hs, cfg); err == nil {
					routes = append(routes, rs...)
					continue
				}
			}
		}
		if nested, ok := rawLookup(m, "config"); ok {
			var cm map[string]json.RawMessage
			if json.Unmarshal(nested, &cm) == nil {
				if c, ok := ParseConfig(cm); ok {
					cfg = mergeConfig(cfg, c)
				}
			}
		}
		if c, ok := ParseConfig(m); ok {
			cfg = mergeConfig(cfg, c)
		}
	}
	if err := sc.Err(); err != nil {
		return nil, cfg, err
	}
	return routes, cfg, nil
}

func mergeConfig(base, over Config) Config {
	if over.LocalAS != 0 {
		base.LocalAS = over.LocalAS
	}
	if over.ClusterID != "" {
		base.ClusterID = over.ClusterID
	}
	if over.RouterID != "" {
		base.RouterID = over.RouterID
	}
	return base
}

func bytesTrimSpace(b []byte) []byte {
	start := 0
	for start < len(b) && (b[start] == ' ' || b[start] == '\t' || b[start] == '\r' || b[start] == '\n') {
		start++
	}
	end := len(b)
	for end > start && (b[end-1] == ' ' || b[end-1] == '\t' || b[end-1] == '\r' || b[end-1] == '\n') {
		end--
	}
	return b[start:end]
}
