```go
package main

import (
	"encoding/json"
	"fmt"
	"net"
	"strconv"
	"strings"
)

// Route is a single BGP path (RIB-in entry) for a prefix.
type Route struct {
	Prefix            string   `json:"prefix"`
	NextHop           string   `json:"next_hop"`
	PeerAddress       string   `json:"peer_address"`
	PeerAS            uint32   `json:"peer_as"`
	PeerType          string   `json:"peer_type"` // "ebgp", "ibgp" or "local"
	ASPath            []uint32 `json:"as_path"`
	Origin            int      `json:"origin"` // 0=IGP, 1=EGP, 2=INCOMPLETE
	LocalPref         uint32   `json:"local_pref"`
	MED               uint32   `json:"med"`
	Weight            uint32   `json:"weight"`
	IGPMetric         uint32   `json:"igp_metric"`
	RouterID          string   `json:"router_id"`
	ClusterList       []string `json:"cluster_list"`
	OriginatorID      string   `json:"originator_id"`
	LocallyOriginated bool     `json:"locally_originated"`
}

// Config holds the local autonomous system identity used for loop rejection.
type Config struct {
	LocalAS   uint32
	ClusterID string
	RouterID  string
}

func rawLookup(m map[string]json.RawMessage, keys ...string) (json.RawMessage, bool) {
	for _, k := range keys {
		if v, ok := m[k]; ok {
			return v, true
		}
	}
	return nil, false
}

func decodeString(raw json.RawMessage) (string, error) {
	var s string
	if err := json.Unmarshal(raw, &s); err == nil {
		return s, nil
	}
	var n json.Number
	if err := json.Unmarshal(raw, &n); err == nil {
		return n.String(), nil
	}
	return "", fmt.Errorf("not a string")
}

func rawToString(m map[string]json.RawMessage, keys ...string) string {
	raw, ok := rawLookup(m, keys...)
	if !ok {
		return ""
	}
	s, err := decodeString(raw)
	if err != nil {
		return ""
	}
	return s
}

func rawToUint(m map[string]json.RawMessage, keys ...string) uint32 {
	raw, ok := rawLookup(m, keys...)
	if !ok {
		return 0
	}
	var n json.Number
	if err := json.Unmarshal(raw, &n); err != nil {
		var s string
		if err := json.Unmarshal(raw, &s); err == nil {
			if v, err := strconv.ParseUint(strings.TrimSpace(s), 10, 32); err == nil {
				return uint32(v)
			}
		}
		return 0
	}
	v, err := strconv.ParseUint(n.String(), 10, 32)
	if err != nil {
		return 0
	}
	return uint32(v)
}

func rawToInt(raw json.RawMessage) int {
	var n json.Number
	if err := json.Unmarshal(raw, &n); err == nil {
		if v, err := strconv.Atoi(n.String()); err == nil {
			return v
		}
	}
	var s string
	if err := json.Unmarshal(raw, &s); err == nil {
		switch strings.ToLower(strings.TrimSpace(s)) {
		case "igp", "i", "0":
			return 0
		case "egp", "e", "1":
			return 1
		case "incomplete", "inc", "?", "2":
			return 2
		}
		if v, err := strconv.Atoi(strings.TrimSpace(s)); err == nil {
			return v
		}
	}
	return 2
}

func toUint32Slice(raw json.RawMessage) []uint32 {
	var nums []json.Number
	if err := json.Unmarshal(raw, &nums); err == nil {
		out := make([]uint32, 0, len(nums))
		for _, n := range nums {
			v, err := strconv.ParseUint(n.String(), 10, 32)
			if err == nil {
				out = append(out, uint32(v))
			}
		}
		return out
	}
	var strs []string
	if err := json.Unmarshal(raw, &strs); err == nil {
		out := make([]uint32, 0, len(strs))
		for _, s := range strs {
			v, err := strconv.ParseUint(strings.TrimSpace(s), 10, 32)
			if err == nil {
				out = append(out, uint32(v))
			}
		}
		return out
	}
	return nil
}

func toStringSlice(raw json.RawMessage) []string {
	var strs []string
	if err := json.Unmarshal(raw, &strs); err == nil {
		return strs
	}
	var one string
	if err := json.Unmarshal(raw, &one); err == nil {
		one = strings.TrimSpace(one)
		if one == "" {
			return nil
		}
		parts := strings.Split(one, " ")
		out := make([]string, 0, len(parts))
		for _, p := range parts {
			if p = strings.TrimSpace(p); p != "" {
				out = append(out, p)
			}
		}
		return out
	}
	return nil
}

// ParseRoute converts a decoded JSON object into a Route.
func ParseRoute(m map[string]json.RawMessage) Route {
	r := Route{
		Prefix:       rawToString(m, "prefix", "nlri", "network"),
		NextHop:      rawToString(m, "next_hop", "nexthop", "next-hop"),
		PeerAddress:  rawToString(m, "peer_address", "peer", "neighbor", "peer_addr"),
		PeerAS:       rawToUint(m, "peer_as", "peeras", "peer-as", "neighbor_as"),
		PeerType:     strings.ToLower(rawToString(m, "peer_type", "peer-type", "type", "session_type")),
		RouterID:     rawToString(m, "router_id", "router-id", "routerid", "peer_router_id"),
		OriginatorID: rawToString(m, "originator_id", "originator-id", "originatorid"),
		LocalPref:    rawToUint(m, "local_pref", "local-pref", "localpref"),
		MED:          rawToUint(m, "med", "multi_exit_discriminator"),
		Weight:       rawToUint(m, "weight", "local_weight"),
		IGPMetric:    rawToUint(m, "igp_metric", "igp-metric", "igpmetric", "metric"),
	}
	if raw, ok := rawLookup(m, "as_path", "as-path", "aspath", "as_paths"); ok {
		r.ASPath = toUint32Slice(raw)
	}
	if raw, ok := rawLookup(m, "cluster_list", "cluster-list", "clusterlist", "cluster_id"); ok {
		r.ClusterList = toStringSlice(raw)
	}
	if raw, ok := rawLookup(m, "origin", "origin_code"); ok {
		r.Origin = rawToInt(raw)
	} else {
		r.Origin = 2
	}
	if raw, ok := rawLookup(m, "locally_originated", "locally-originated", "local_origin", "is_local"); ok {
		var b bool
		if err := json.Unmarshal(raw, &b); err == nil {
			r.LocallyOriginated = b
		}
	}
	if r.PeerType == "local" || r.PeerType == "self" {
		r.LocallyOriginated = true
	}
	if r.PeerAddress == "" {
		r.PeerAddress = r.NextHop
	}
	if r.RouterID == "" {
		r.RouterID = r.PeerAddress
	}
	return r
}

// ParseConfig extracts the local identity from a JSON object.
func ParseConfig(m map[string]json.RawMessage) (Config, bool) {
	c := Config{
		LocalAS:   rawToUint(m, "local_as", "local-as", "our_asn", "local_asn", "my_asn"),
		ClusterID: rawToString(m, "cluster_id", "cluster-id", "clusterid", "our_cluster_id"),
		RouterID:  rawToString(m, "router_id", "router-id", "local_router_id", "bgp_identifier"),
	}
	if c.LocalAS == 0 && c.ClusterID == "" && c.RouterID == "" {
		return c, false
	}
	return c, true
}

func ipKey(s string) []byte {
	ip := net.ParseIP(strings.TrimSpace(s))
	if ip == nil {
		return []byte(strings.TrimSpace(s))
	}
	if v4 := ip.To4(); v4 != nil {
		return v4
	}
	return ip.To16()
}

func cmpIP(a, b string) int {
	return strings.Compare(string(ipKey(a)), string(ipKey(b)))
}

func canonicalPrefix(p string) (string, bool) {
	ip, ipnet, err := net.ParseCIDR(p)
	if err != nil {
		return p, false
	}
	ones, _ := ipnet.Mask.Size()
	return ip.Mask(ipnet.Mask).String() + "/" + strconv.Itoa(ones), true
}

func prefixSortKey(p string) ([]byte, int) {
	ip, ipnet, err := net.ParseCIDR(p)
	if err != nil {
		return []byte(p), 0
	}
	ones, _ := ipnet.Mask.Size()
	return ip.Mask(ipnet.Mask), ones
}
