### `select.go`
```go
package main

import (
	"bytes"
	"fmt"
	"sort"
)

// Stage names reported in the decisive_stage field.
const (
	StageOnlyPath          = "only_path"
	StageWeight            = "weight"
	StageLocalPref         = "local_pref"
	StageLocallyOriginated = "locally_originated"
	StageASPathLength      = "as_path_length"
	StageOrigin            = "origin"
	StageMED               = "med"
	StageEBGPOverIBGP      = "ebgp_over_ibgp"
	StageIGPMetric         = "igp_metric"
	StageRouterID          = "router_id"
	StagePeerAddress       = "peer_address"
)

// Decision is the result of running best-path selection for one prefix.
type Decision struct {
	Prefix        string
	NextHop       string
	ASPath        []uint32
	DecisiveStage string
	Multipath     []string
}

func normalizeASPath(p []uint32) []uint32 {
	if p == nil {
		return []uint32{}
	}
	return p
}

// looped reports whether a path must be rejected for AS / route-reflector loop
// reasons: AS_PATH contains our ASN, or CLUSTER_LIST carries our cluster ID.
// rejectOriginator additionally applies the RFC 4456 ORIGINATOR_ID check.
func looped(r Route, cfg Config, rejectOriginator bool) bool {
	for _, as := range r.ASPath {
		if as == cfg.LocalAS && cfg.LocalAS != 0 {
			return true
		}
	}
	if cfg.ClusterID != "" {
		for _, cl := range r.ClusterList {
			if sameIP(cl, cfg.ClusterID) {
				return true
			}
		}
	}
	if rejectOriginator && cfg.RouterID != "" && r.OriginatorID != "" && sameIP(r.OriginatorID, cfg.RouterID) {
		return true
	}
	return false
}

func sameIP(a, b string) bool {
	return string(ipKey(a)) == string(ipKey(b))
}

// applyMED reduces the candidate set using MULTI_EXIT_DISC, but only within
// paths learned from the same neighbouring AS (RFC 4271 §9.1.2.2). Each AS
// group independently keeps its lowest-MED paths; groups are unioned so MED is
// never used to eliminate a whole neighbouring AS.
func applyMED(cands []Route) []Route {
	type group struct {
		best uint32
		seen bool
	}
	groups := map[uint32]*group{}
	for _, c := range cands {
		g := groups[c.PeerAS]
		if g == nil {
			g = &group{}
			groups[c.PeerAS] = g
		}
		if !g.seen || c.MED < g.best {
			g.best = c.MED
			g.seen = true
		}
	}
	out := make([]Route, 0, len(cands))
	for _, c := range cands {
		if c.MED == groups[c.PeerAS].best {
			out = append(out, c)
		}
	}
	return out
}

func originRank(o int) int {
	if o < 0 || o > 2 {
		return 2
	}
	return o
}

func ebgpRank(t string) int {
	switch t {
	case "ebgp", "external", "local", "self":
		return 2
	default:
		return 1
	}
}

// SelectBest runs the full decision process over the candidate paths for a
// single prefix. Each candidate must already have passed loop rejection.
func SelectBest(prefix string, cands []Route) (Decision, bool) {
	if len(cands) == 0 {
		return Decision{}, false
	}
	dec := Decision{Prefix: prefix}
	if len(cands) == 1 {
		dec.NextHop = cands[0].NextHop
		dec.ASPath = normalizeASPath(cands[0].ASPath)
		dec.DecisiveStage = StageOnlyPath
		dec.Multipath = []string{cands[0].NextHop}
		return dec, true
	}

	cur := cands
	decisive := ""
	reduce := func(stage string, key func(Route) int64) {
		if len(cur) <= 1 {
			return
		}
		best := key(cur[0])
		for _, c := range cur[1:] {
			if k := key(c); k < best {
				best = k
			}
		}
		next := make([]Route, 0, len(cur))
		for _, c := range cur {
			if key(c) == best {
				next = append(next, c)
			}
		}
		if len(next) < len(cur) {
			decisive = stage
			cur = next
		}
	}

	// 1. WEIGHT (higher is better).
	reduce(StageWeight, func(r Route) int64 { return -int64(r.Weight) })
	// 2. LOCAL_PREF (higher is better).
	reduce(StageLocalPref, func(r Route) int64 { return -int64(r.LocalPref) })
	// 3. Locally originated (preferred over learned).
	reduce(StageLocallyOriginated, func(r Route) int64 {
		if r.LocallyOriginated {
			return 0
		}
		return 1
	})
	// 4. Shortest AS_PATH.
	reduce(StageASPathLength, func(r Route) int64 { return int64(len(r.ASPath)) })
	// 5. Lowest ORIGIN.
	reduce(StageOrigin, func(r Route) int64 { return int64(originRank(r.Origin)) })
	// 6. MED, restricted to the same neighbouring AS.
	if len(cur) > 1 {
		if next := applyMED(cur); len(next) < len(cur) {
			decisive = StageMED
			cur = next
		}
	}
	// 7. eBGP preferred over iBGP.
	reduce(StageEBGPOverIBGP, func(r Route) int64 { return int64(-ebgpRank(r.PeerType)) })
	// 8. Lowest IGP metric to the next hop.
	reduce(StageIGPMetric, func(r Route) int64 { return int64(r.IGPMetric) })

	// Everything still in cur is equal cost and forms the multipath set.
	multipath := append([]Route(nil), cur...)

	// 9. Lowest router ID.
	reduce(StageRouterID, func(r Route) int64 { return int64(ipToUint(r.RouterID)) })
	// 10. Lowest peer address.
	reduce(StagePeerAddress, func(r Route) int64 { return int64(ipToUint(r.PeerAddress)) })

	// Final deterministic fallback if peer addresses also collide.
	if len(cur) > 1 {
		minNH := cur[0].NextHop
		for _, c := range cur[1:] {
			if cmpIP(c.NextHop, minNH) < 0 {
				minNH = c.NextHop
			}
		}
		next := make([]Route, 0, len(cur))
		for _, c := range cur {
			if c.NextHop == minNH {
				next = append(next, c)
			}
		}
		cur = next
	}

	winner := cur[0]
	dec.NextHop = winner.NextHop
	dec.ASPath = normalizeASPath(winner.ASPath)
	dec.DecisiveStage = decisive
	if dec.DecisiveStage == "" {
		dec.DecisiveStage = StagePeerAddress
	}
	dec.Multipath = multipathNextHops(multipath)
	return dec, true
}

func multipathNextHops(rs []Route) []string {
	set := make(map[string]struct{}, len(rs))
	for _, r := range rs {
		set[r.NextHop] = struct{}{}
	}
	out := make([]string, 0, len(set))
	for nh := range set {
		out = append(out, nh)
	}
	sort.Slice(out, func(i, j int) bool { return cmpIP(out[i], out[j]) < 0 })
	return out
}

func ipToUint(s string) uint64 {
	b := ipKey(s)
	var v uint64
	for i := 0; i < len(b) && i < 8; i++ {
		v = v<<8 | uint64(b[i])
	}
	return v
}

// ProcessPrefix groups routes by prefix, rejects loops and selects the best
// path for each prefix, returning entries in numeric prefix order.
func ProcessPrefix(routes []Route, cfg Config, rejectOriginator bool) []Decision {
	byPrefix := make(map[string][]Route)
	order := make([]string, 0)
	for _, r := range routes {
		cp, ok := canonicalPrefix(r.Prefix)
		if !ok {
			cp = r.Prefix
		}
		if _, seen := byPrefix[cp]; !seen {
			order = append(order, cp)
		}
		byPrefix[cp] = append(byPrefix[cp], r)
	}

	var out []Decision
	for _, p := range order {
		var valid []Route
		for _, r := range byPrefix[p] {
			if r.LocallyOriginated && len(r.ASPath) == 0 {
				valid = append(valid, r)
				continue
			}
			if looped(r, cfg, rejectOriginator) {
				continue
			}
			valid = append(valid, r)
		}
		if len(valid) == 0 {
			continue
		}
		if d, ok := SelectBest(p, valid); ok {
			out = append(out, d)
		}
	}

	sort.Slice(out, func(i, j int) bool {
		ai, al := prefixSortKey(out[i].Prefix)
		bi, bl := prefixSortKey(out[j].Prefix)
		if c := bytes.Compare(ai, bi); c != 0 {
			return c < 0
		}
		return al < bl
	})
	return out
}

func (d Decision) String() string {
	return fmt.Sprintf("%s via %s [%s] %v", d.Prefix, d.NextHop, d.DecisiveStage, d.Multipath)
}
